package com.colonellp.ellamonitor;

import org.json.*;
import org.junit.Test;
import java.util.*;
import java.time.*;
import static org.junit.Assert.*;

public class BmsLoadTest {
    JSONObject catalogue()throws Exception{JSONObject c=ContractTest.catalogue();c.getJSONArray("metrics").put(ContractTest.metric("pv1-test","sbms","electrical","supply","pv1",0)).put(ContractTest.metric("external-test","sbms","electrical","load","externalLoad",0));return c;}
    JSONObject live(double pv,double battery)throws Exception{JSONObject l=ContractTest.live();for(int i=0;i<l.getJSONArray("measurements").length();i++){JSONObject m=l.getJSONArray("measurements").getJSONObject(i);if(m.getString("id").equals("bms-test"))m.getJSONObject("values").put("current",battery);}for(String id:new String[]{"pv1-test","external-test"})l.getJSONArray("measurements").put(new JSONObject().put("id",id).put("fresh",true).put("mappingValid",true).put("values",new JSONObject().put("current",id.equals("pv1-test")?pv:99)));return l;}
    @Test public void pvMinusSignedBatteryIsStableAsSolarIncreases()throws Exception{List<MonitorData.Metric> metrics=MonitorData.catalogue(catalogue());String old=metrics.stream().filter(m->m.channel.equals("externalLoad")).findFirst().get().alias+":current";for(double[] pair:new double[][]{{0,-3},{2,-1},{5,2},{0,0}}){Map<String,MonitorData.Datum> d=MonitorData.display(metrics,live(pair[0],pair[1]),0);MonitorData.Datum load=ContractTest.find(d,"sbmsLoad","current");assertEquals(pair[0]-pair[1],load.value,0);assertEquals(old,load.id);assertEquals("derived:sbms-load",load.metric.id);}assertEquals("external-test",metrics.stream().filter(m->m.channel.equals("externalLoad")).findFirst().get().id);}
    @Test public void missingStaleOrMismappedInputsNeverBecomeZero()throws Exception{List<MonitorData.Metric> metrics=MonitorData.catalogue(catalogue());JSONObject l=live(5,2);l.getJSONObject("sbms").put("fresh",false);assertNull(ContractTest.find(MonitorData.display(metrics,l,0),"sbmsLoad","current").value);l=live(5,2);l.getJSONArray("measurements").getJSONObject(4).put("mappingValid",false);assertNull(ContractTest.find(MonitorData.display(metrics,l,0),"sbmsLoad","current").value);l=live(5,2);l.getJSONArray("measurements").getJSONObject(1).getJSONObject("values").put("current",JSONObject.NULL);assertNull(ContractTest.find(MonitorData.display(metrics,l,0),"sbmsLoad","current").value);assertNull(ContractTest.find(MonitorData.display(metrics,live(5,2),4),"sbmsLoad","current").value);}
    @Test public void historyAndCsvUsePv1MinusBatteryAndPreserveRawExternal()throws Exception{PopupHistoryTest h=new PopupHistoryTest();PopupHistory.Plan p=PopupHistory.plan(h.now,h.selection(0,true),h.utc);MonitorData.Metric virtual=DerivedHistory.bmsLoad(MonitorData.catalogue(catalogue()));assertEquals("pv1-test",virtual.definition.getJSONArray("components").getJSONObject(0).getJSONObject("metric").getString("id"));assertEquals(-1,virtual.definition.getJSONArray("components").getJSONObject(1).getInt("factor"));HistoryData.Record pv=h.row(p.query.from,60,5,65,60,false),battery=h.row(p.query.from,60,2,26,60,false);HistoryData.Result combined=DerivedHistory.combine(virtual,p.query,Arrays.asList(h.result(virtual,p,pv),h.result(virtual,p,battery)),new double[]{1,-1});assertEquals(3,combined.rows.get(0).value("current","electrical"),0);assertEquals(39,combined.rows.get(0).value("watts","electrical"),0);assertEquals(.05,SummaryPeriods.totals(combined).charge,1e-12);assertEquals(.65,SummaryPeriods.totals(combined).energy,1e-12);assertEquals(5,pv.value("current","electrical"),0);assertTrue(HistoryData.csv(combined,"Load [BMS]").contains("pv1-test × 1"));assertTrue(HistoryData.csv(combined,"Load [BMS]").contains("bms-test × -1"));}
    @Test public void alignedAtomicSbmsCoverageKeepsGapsAndRejectsMismatchedSnapshots()throws Exception{PopupHistoryTest h=new PopupHistoryTest();PopupHistory.Plan p=PopupHistory.plan(h.now,h.selection(0,true),h.utc);MonitorData.Metric virtual=DerivedHistory.bmsLoad(MonitorData.catalogue(catalogue()));HistoryData.Record pv=h.row(p.query.from,60,5,65,30,false),battery=h.row(p.query.from,60,2,26,30,false);List<HistoryData.Result> inputs=Arrays.asList(h.result(virtual,p,pv),h.result(virtual,p,battery));HistoryData.Result combined=DerivedHistory.combine(virtual,p.query,inputs,new double[]{1,-1});assertEquals(1,combined.rows.size());assertEquals(30,combined.rows.get(0).coverage("current","electrical"),0);assertEquals(.025,SummaryPeriods.totals(combined).charge,1e-12);assertFalse(PopupHistory.series(combined,p,"current",false,true).points.get(0).complete);battery.raw.put("currentLastAt",battery.raw.getLong("currentLastAt")+1);assertTrue(DerivedHistory.combine(virtual,p.query,inputs,new double[]{1,-1}).rows.isEmpty());}
    @Test public void unknownComponentHistoryDoesNotInventATotal()throws Exception{PopupHistoryTest h=new PopupHistoryTest();PopupHistory.Plan p=PopupHistory.plan(h.now,h.selection(0,true),h.utc);MonitorData.Metric virtual=DerivedHistory.bmsLoad(MonitorData.catalogue(catalogue()));assertTrue(DerivedHistory.combine(virtual,p.query,Arrays.asList(h.result(virtual,p,h.row(p.query.from,60,5,65,60,false)),h.result(virtual,p)),new double[]{1,-1}).rows.isEmpty());}
}
